#!/usr/bin/env node
/**
 * Emits the utility classes described by `utilities.spec.mjs`.
 *
 * Run with `--check` to verify the checked-in output matches a fresh run
 * without writing anything; that is what CI uses, so the generated file can
 * never drift from the spec that describes it.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import {
  BREAKPOINTS,
  BREAKPOINTS_CASCADE,
  ALIGN_ALIGNMENTS,
  BACKGROUND_RAMPS,
  BORDER_SIDES,
  BORDER_STYLES,
  BORDER_WIDTHS,
  CURSORS,
  GRID_COLUMNS,
  MAX_WIDTH_SIZES,
  ON_RAMPS,
  OPACITY_STEPS,
  OVERFLOW_RULES,
  POINTER_EVENTS,
  RADIUS_CORNERS,
  RADIUS_NESTS,
  RADIUS_SIZES,
  SCHEMES,
  SCROLLBAR_RULES,
  SHADOW_SIZES,
  SIZE_RULES,
  SELECTION_GROUPS,
  TRANSITIONS,
  Z_INDEX_STEPS,
  cursorValue,
  gridTemplate,
  WEIGHTS,
  JUSTIFY_ALIGNMENTS,
  FLEX_DIRECTIONS,
  FLEX_VALUES,
  FONT_SCALING,
  FONT_SIZES,
  FONT_TYPES,
  FONT_WEIGHTS,
  FLEX_WRAP,
  OFFSET_SIDES,
  OFFSET_TOKENS,
  POSITION_VALUES,
  SPACING_EXTRAS,
  SPACING_FAMILIES,
  SPACING_TOKENS,
  offsetValue,
  spacingVar,
} from "./utilities.spec.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");

const BANNER = `/* GENERATED by scripts/generate-utilities.mjs — do not edit.
 * The class matrix lives in scripts/utilities.spec.mjs; change it there and
 * re-run \`pnpm generate:utilities\`. */\n`;

const rule = (selector, decls) =>
  `${selector} {\n${decls.map((d) => `  ${d}\n`).join("")}}\n`;

function spacing() {
  const out = [];
  for (const { prefix, props } of SPACING_FAMILIES) {
    out.push(`/* ${props.join(", ")} */`);
    for (const token of SPACING_TOKENS) {
      out.push(rule(`.${prefix}-${token}`, props.map((p) => `${p}: ${spacingVar(token)};`)));
    }
    out.push("");
  }
  for (const { selector, decls } of SPACING_EXTRAS) {
    out.push(rule(selector, decls));
  }

  // The responsive matrix. Until this existed, a token in a breakpoint prop —
  // `s={{ gap: "4" }}`, which is what every doc and example teaches — resolved
  // to nothing at all: no class existed for it, and ClientFlex's inline path
  // guards on `typeof value === "number"`, so the string fell through both.
  // Numbers worked, tokens did not, and neither said so.
  for (const { key, query } of BREAKPOINTS_CASCADE) {
    const body = SPACING_FAMILIES.flatMap(({ prefix, props }) =>
      SPACING_TOKENS.map((token) =>
        rule(`.${key}-${prefix}-${token}`, props.map((p) => `${p}: ${spacingVar(token)};`)),
      ),
    )
      .join("\n")
      .replace(/^/gm, "  ")
      .replace(/^\s+$/gm, "");
    out.push(`@media ${query} {\n${body}}\n`);
  }
  return out.join("\n");
}

/**
 * Every rule a breakpoint repeats, as `[selectorSuffix, declarations]`. The
 * base pass emits them unprefixed; each breakpoint pass emits the same list
 * prefixed and wrapped in its media query. Writing the matrix once is the
 * whole point — position.scss was 1,548 lines because it wrote it five times.
 */
function positionRules() {
  const rules = [];
  for (const value of POSITION_VALUES) {
    rules.push([`position-${value}`, [`position: ${value};`]]);
  }
  for (const side of OFFSET_SIDES) {
    for (const token of OFFSET_TOKENS) {
      rules.push([`${side}-${token}`, [`${side}: ${offsetValue(token)};`]]);
    }
  }
  return rules;
}

function position() {
  const rules = positionRules();
  const out = [rules.map(([sel, decls]) => rule(`.${sel}`, decls)).join("\n")];

  for (const { key, query } of BREAKPOINTS_CASCADE) {
    const body = rules
      .map(([sel, decls]) => rule(`.${key}-${sel}`, decls))
      .join("\n")
      .replace(/^/gm, "  ")
      .replace(/^\s+$/gm, "");
    out.push(`@media ${query} {\n${body}}\n`);
  }
  return out.join("\n");
}

/**
 * Sass cannot be read by a generator, so the widths used to be written twice —
 * here and in breakpoints.scss — and a test pinned them together. Generating
 * the Sass from the same list removes the second copy instead.
 *
 * This one keeps its plain filename rather than taking a `.generated` suffix:
 * ten call sites `@use` it by name, including core component modules that
 * reach it through the synced copy, and renaming buys nothing.
 */
function breakpoints() {
  // The variables carry the raw widths, as they always have — component modules
  // interpolate them. The mixins carry the whole query, because `xl` is a
  // min-width step and cannot be rebuilt from a width alone.
  const vars = BREAKPOINTS.map(
    ({ key, query }) => `$breakpoint-${key}: ${query.match(/(\d+)px/)[1]}px;`,
  ).join("\n");
  const mixins = BREAKPOINTS.map(
    ({ key, query }) => `@mixin ${key} {\n  @media ${query} {\n    @content;\n  }\n}`,
  ).join("\n\n");
  return `${vars}\n\n${mixins}\n`;
}

/** The rules every breakpoint repeats — direction, alignment, and show/hide. */
function flexResponsiveRules() {
  const rules = [
    ["flex-hide", ["display: none;"]],
    ["flex-show", ["display: flex;"]],
  ];
  for (const dir of FLEX_DIRECTIONS) rules.push([`flex-${dir}`, [`flex-direction: ${dir};`]]);
  for (const { suffix, value } of JUSTIFY_ALIGNMENTS) {
    rules.push([`justify-${suffix}`, [`justify-content: ${value};`]]);
  }
  for (const { suffix, value } of ALIGN_ALIGNMENTS) {
    rules.push([`align-${suffix}`, [`align-items: ${value};`]]);
  }
  rules.push(["center", ["align-items: center;", "justify-content: center;"]]);

  // ServerFlex emits `.<bp>-flex-<n>` and `.<bp>-flex-wrap` for a breakpoint
  // `flex` or `wrap`, and neither class existed — the prop reached the DOM as
  // a class name with no rule behind it.
  for (const { suffix, value } of FLEX_WRAP) rules.push([suffix, [`flex-wrap: ${value};`]]);
  for (const value of FLEX_VALUES) rules.push([`flex-${value}`, [`flex: ${value};`]]);
  return rules;
}

function flex() {
  const out = [];

  out.push(rule(".display-flex", ["display: flex;"]));
  out.push(rule(".display-inline-flex", ["display: inline-flex;"]));

  for (const dir of FLEX_DIRECTIONS) {
    out.push(rule(`.flex-${dir}`, [`flex-direction: ${dir};`]));
  }

  // `.<bp>-flex-show` is hidden by default and revealed inside its own query,
  // so the pair reads as "show only at this width". The hand-written file had
  // this for l, m and s and omitted it for xs, which left `.xs-flex-show`
  // visible at every width instead of only the narrowest — the one place the
  // four siblings disagreed, and invisible without comparing them side by side.
  for (const { key } of BREAKPOINTS_CASCADE) {
    out.push(rule(`.${key}-flex-show`, ["display: none;"]));
  }

  for (const { suffix, value } of JUSTIFY_ALIGNMENTS) {
    out.push(rule(`.justify-${suffix}`, [`justify-content: ${value};`]));
  }
  for (const { suffix, value } of ALIGN_ALIGNMENTS) {
    out.push(rule(`.align-${suffix}`, [`align-items: ${value};`]));
  }
  out.push(rule(".center", ["align-items: center;", "justify-content: center;"]));

  for (const { suffix, value } of FLEX_WRAP) out.push(rule(`.${suffix}`, [`flex-wrap: ${value};`]));
  for (const value of FLEX_VALUES) out.push(rule(`.flex-${value}`, [`flex: ${value};`]));

  out.push(rule(".flex-hide", ["display: none;"]));
  out.push(rule(".flex-show", ["display: flex;"]));

  const responsive = flexResponsiveRules();
  for (const { key, query } of BREAKPOINTS_CASCADE) {
    const body = responsive
      .map(([sel, decls]) => rule(`.${key}-${sel}`, decls))
      .join("\n")
      .replace(/^/gm, "  ")
      .replace(/^\s+$/gm, "");
    out.push(`@media ${query} {\n${body}}\n`);
  }
  return out.join("\n");
}

function border() {
  const out = [];

  // `border-radius: none` is not a valid declaration — the parser rejects it
  // and the element falls back to the initial 0px, so this class only ever
  // worked by accident. It is emitted as `0`, which renders identically and is
  // actually a rule. It stays first, as it was, so nothing about which class
  // wins a collision changes.
  out.push(rule(".radius-none", ["border-radius: 0;"]));

  for (const size of RADIUS_SIZES) {
    out.push(rule(`.radius-${size}`, [`border-radius: var(--radius-${size});`]));
    for (const nest of RADIUS_NESTS) {
      out.push(rule(`.radius-${size}-${nest}`, [`border-radius: var(--radius-${size}-nest-${nest});`]));
    }
  }
  out.push(rule(".radius-full", ["border-radius: var(--radius-full);"]));

  // `full` rounds corners like any other step, so it joins the sized ones here.
  const cornerSizes = [...[...RADIUS_SIZES].reverse(), "full"];
  for (const { suffix, corners } of RADIUS_CORNERS) {
    for (const size of cornerSizes) {
      out.push(
        rule(
          `.radius-${size}-${suffix}`,
          corners.map((c) => `border-${c}-radius: var(--radius-${size});`),
        ),
      );
    }
  }

  for (const style of BORDER_STYLES) out.push(rule(`.border-${style}`, [`border-style: ${style};`]));
  for (const w of BORDER_WIDTHS) out.push(rule(`.border-${w}`, [`border-width: ${w}px;`]));
  out.push(
    rule(".border-reset", [
      "border-top-width: 0;",
      "border-right-width: 0;",
      "border-bottom-width: 0;",
      "border-left-width: 0;",
    ]),
  );
  for (const { suffix, props } of BORDER_SIDES) {
    out.push(rule(`.border-${suffix}-1`, props.map((p) => `${p}: 1px;`)));
  }

  out.push(rule(".surface-border", ["border-color: var(--surface-border);"]));
  out.push(rule(".transparent-border", ["border-color: var(--static-transparent);"]));
  out.push(rule(".default-border", ["border-color: var(--default-border);"]));

  for (const scheme of SCHEMES) {
    for (const weight of WEIGHTS) {
      out.push(rule(`.${scheme}-border-${weight}`, [`border-color: var(--${scheme}-border-${weight});`]));
    }
    // The alpha ramp is named `--<scheme>-alpha-<weight>`, not `-border-alpha-`.
    for (const weight of WEIGHTS) {
      out.push(rule(`.${scheme}-border-alpha-${weight}`, [`border-color: var(--${scheme}-alpha-${weight});`]));
    }
  }
  return out.join("\n");
}

function background() {
  const out = [
    rule(".page-background", ["background-color: var(--page-background);"]),
    rule(".surface-background", [
      "background-color: var(--surface-background);",
      "backdrop-filter: var(--backdrop-filter);",
    ]),
    rule(".overlay-background", ["background-color: var(--backdrop);"]),
    // `background="transparent"` and `solid="transparent"` are in the prop
    // types and had no class to resolve to, so they fell through to
    // `transparent-border` — which did nothing to the background and quietly
    // cleared the author's border. These are the two that were missing.
    rule(".transparent-background", ["background-color: var(--static-transparent);"]),
    rule(".transparent-solid", ["background-color: var(--static-transparent);"]),
  ];

  for (const scheme of SCHEMES) {
    for (const { ramps, decls } of SELECTION_GROUPS) {
      const selectors = ramps.flatMap((ramp) =>
        WEIGHTS.map((w) => `.${scheme}-${ramp}-${w} ::selection`),
      );
      out.push(rule(selectors.join(",\n"), decls(scheme)));
    }
    for (const { suffix, token } of BACKGROUND_RAMPS) {
      for (const w of WEIGHTS) {
        out.push(rule(`.${scheme}-${suffix}-${w}`, [`background-color: var(${token(scheme, w)});`]));
      }
    }
  }
  return out.join("\n");
}

function display() {
  const out = OVERFLOW_RULES.map(({ suffix, prop, value }) =>
    rule(`.${suffix}`, [`${prop}: ${value};`]),
  );
  for (const { selector, decls } of SCROLLBAR_RULES) out.push(rule(selector, decls));

  for (const { key, query } of BREAKPOINTS_CASCADE) {
    const rules = [
      ...OVERFLOW_RULES.map(({ suffix, prop, value }) => [suffix, [`${prop}: ${value};`]]),
      // ServerFlex emits all four of these for a breakpoint prop, and none of
      // the classes existed: `s={{ opacity: 50 }}` and its siblings reached the
      // DOM as a class name with no rule behind it, in both the class path and
      // the inline one, which guards on other prop names entirely.
      ...OPACITY_STEPS.map((step) => [`opacity-${step}`, [`opacity: ${Number(step) / 100};`]]),
      ...Z_INDEX_STEPS.map((z) => [`z-index-${z}`, [`z-index: ${z};`]]),
      ...TRANSITIONS.map((t) => [`transition-${t}`, [`transition: var(--transition-${t});`]]),
      ...POINTER_EVENTS.map((pe) => [`pointer-events-${pe}`, [`pointer-events: ${pe};`]]),
    ];
    const body = [
      ...rules.map(([sel, decls]) => rule(`.${key}-${sel}`, decls)),
      // The scrollbar is a set of pseudo-elements, so its breakpoint variant
      // has to carry all five rather than one class.
      ...SCROLLBAR_RULES.map(({ selector, decls }) =>
        rule(selector.replace(".scrollbar-minimal", `.${key}-scrollbar-minimal`), decls),
      ),
    ]
      .join("\n")
      .replace(/^/gm, "  ")
      .replace(/^\s+$/gm, "");
    out.push(`@media ${query} {\n${body}}\n`);
  }

  // These follow the breakpoint blocks, as they did in the hand-written file.
  for (const step of OPACITY_STEPS) {
    out.push(rule(`.opacity-${step}`, [`opacity: ${Number(step) / 100};`]));
  }
  for (const z of Z_INDEX_STEPS) out.push(rule(`.z-index-${z}`, [`z-index: ${z};`]));
  for (const t of TRANSITIONS) {
    out.push(rule(`.transition-${t}`, [`transition: var(--transition-${t});`]));
  }
  for (const pe of POINTER_EVENTS) out.push(rule(`.pointer-events-${pe}`, [`pointer-events: ${pe};`]));
  for (const c of CURSORS) out.push(rule(`.cursor-${c}`, [`cursor: ${cursorValue(c)};`]));

  return out.join("\n");
}

function grid() {
  const out = [rule(".display-grid", ["display: grid;"])];

  for (const n of GRID_COLUMNS) {
    out.push(rule(`.columns-${n}`, [`grid-template-columns: ${gridTemplate(n)};`]));
  }

  // The same pairing `flex.scss` uses: hidden by a base rule, revealed inside
  // its own query, so `.<bp>-grid-show` means "show only at this width". The
  // hand-written file had none of these four base rules, so every
  // `.<bp>-grid-show` was visible at every width — measured in Chromium, all
  // four computed `block` above their breakpoint where they should have
  // computed `none`. Flex had the same hole at xs alone; grid had it at all of
  // them, and no call site in the fleet had noticed.
  for (const { key } of BREAKPOINTS_CASCADE) {
    out.push(rule(`.${key}-grid-show`, ["display: none;"]));
  }

  out.push(rule(".grid-hide", ["display: none;"]));
  out.push(rule(".grid-show", ["display: grid;"]));

  for (const { key, query } of BREAKPOINTS_CASCADE) {
    const rules = [
      ...GRID_COLUMNS.map((n) => [`columns-${n}`, [`grid-template-columns: ${gridTemplate(n)};`]]),
      ["grid-hide", ["display: none;"]],
      ["grid-show", ["display: grid;"]],
    ];
    const body = rules
      .map(([sel, decls]) => rule(`.${key}-${sel}`, decls))
      .join("\n")
      .replace(/^/gm, "  ")
      .replace(/^\s+$/gm, "");
    out.push(`@media ${query} {\n${body}}\n`);
  }
  return out.join("\n");
}

function color() {
  const out = [rule(".color-inherit", ["color: inherit;"])];
  for (const scheme of SCHEMES) {
    for (const ramp of ON_RAMPS) {
      for (const weight of WEIGHTS) {
        out.push(rule(`.${scheme}-${ramp}-${weight}`, [`color: var(--${scheme}-${ramp}-${weight});`]));
      }
    }
  }
  return out.join("\n");
}

function shadow() {
  return SHADOW_SIZES.map((size) => rule(`.shadow-${size}`, [`box-shadow: var(--shadow-${size});`])).join("\n");
}

function size() {
  const out = SIZE_RULES.map(({ selector, decls }) => rule(selector, decls));
  for (const s of MAX_WIDTH_SIZES) {
    out.push(rule(`.max-width-${s}`, [`max-width: var(--responsive-width-${s});`]));
  }
  // Flex and grid children refuse to shrink below their content without these.
  out.push(rule(".min-width-0", ["min-width: 0;"]));
  out.push(rule(".min-height-0", ["min-height: 0;"]));
  return out.join("\n");
}

function typography() {
  const out = [
    rule("html", [
      "font-size: var(--font-scaling-desktop);",
      "font-family: var(--font-body);",
      "font-weight: var(--font-weight-normal);",
      "color: var(--neutral-on-background-strong);",
    ]),
    rule("h1, h2, h3, h4, h5, h6, p", ["margin: 0;"]),
    rule(".font-size-inherit", ["font-size: inherit;"]),
    rule(".font-weight-inherit", ["font-weight: inherit;"]),
  ];

  // All four weights read the display ramp, whatever family they land on.
  for (const w of FONT_WEIGHTS) {
    out.push(rule(`.font-${w}`, [`font-weight: var(--font-weight-display-${w});`]));
  }

  for (const { name, family, scale, tracking } of FONT_TYPES) {
    out.push(rule(`.font-${name}`, [`font-family: var(--font-${family});`]));
    for (const size of FONT_SIZES) {
      const decls = [
        `font-size: calc(var(--font-size-${scale}-${size}) * var(--font-size-${scale}-multiplier));`,
      ];
      if (tracking?.[size]) decls.push(`letter-spacing: ${tracking[size]};`);
      decls.push(
        `line-height: calc(var(--line-height-${scale}-${size}) * var(--line-height-${scale}-multiplier));`,
      );
      // Both a combined and a descendant selector, so the size can sit on the
      // same element as the family or on a child of it.
      out.push(rule(`.font-${name}.font-${size},\n.font-${name} > .font-${size}`, decls));
    }
  }

  for (const { name, family } of FONT_TYPES) {
    out.push(rule(`.font-family-${name}`, [`font-family: var(--font-${family});`]));
  }

  for (const { key, value } of FONT_SCALING) {
    const { query } = BREAKPOINTS.find((b) => b.key === key);
    out.push(`@media ${query} {\n  html {\n    font-size: ${value};\n  }\n}\n`);
  }
  return out.join("\n");
}

const TARGETS = [
  { file: "scss/styles/breakpoints.scss", build: breakpoints },
  { file: "scss/styles/typography.generated.scss", build: typography },
  { file: "scss/styles/color.generated.scss", build: color },
  { file: "scss/styles/shadow.generated.scss", build: shadow },
  { file: "scss/styles/size.generated.scss", build: size },
  { file: "scss/styles/grid.generated.scss", build: grid },
  { file: "scss/styles/display.generated.scss", build: display },
  { file: "scss/styles/background.generated.scss", build: background },
  { file: "scss/styles/border.generated.scss", build: border },
  { file: "scss/styles/flex.generated.scss", build: flex },
  { file: "scss/styles/spacing.generated.scss", build: spacing },
  { file: "scss/styles/position.generated.scss", build: position },
];

const check = process.argv.includes("--check");
let drift = false;

for (const { file, build } of TARGETS) {
  const path = join(ROOT, file);
  const next = BANNER + "\n" + build();
  const current = (() => {
    try {
      return readFileSync(path, "utf8");
    } catch {
      return null;
    }
  })();

  if (check) {
    if (current !== next) {
      drift = true;
      console.error(`drift: ${file} does not match the spec — run \`pnpm generate:utilities\``);
    }
    continue;
  }

  if (current === next) {
    console.log(`unchanged  ${file}`);
    continue;
  }
  writeFileSync(path, next);
  const classes = (next.match(/^\./gm) || []).length;
  console.log(`written    ${file} (${classes} classes)`);
}

if (check && drift) process.exit(1);
if (check) console.log("generated utilities are up to date");
